-- Store.Capture, first statement: keep one notification. Run in a short Write transaction with
-- trim_mail.sql after it. Use Exec (one row, or an error).
-- Args: $1 id uuid (a new MailID, generated by the caller), $2 to_address text (as notify gave
-- it; list_mail.sql matches it case-insensitively), $3 subject text, $4 body text,
-- $5 message_id text (Envelope.MessageID), $6 captured_at timestamptz (the service clock).
-- Columns: none.
-- Fails 25006 (db.ErrReadOnly) on a read-only copy: Unavailable, notify retries (F28).
-- Constraint errors (*db.Error.Constraint, all Invalid; Channel.Send validates the envelope
-- first, so reaching one is a bug, except that a rendered text with a control character is
-- already refused by notify): demo_mail_pkey is Conflict (a duplicate random ID),
-- demo_mail_nil_uuid_chk, demo_mail_to_address_chk, demo_mail_subject_chk, demo_mail_body_chk,
-- demo_mail_message_id_chk.
-- Never log the arguments: to_address, subject and body are personal.
INSERT INTO core.demo_mail (id, to_address, subject, body, message_id, captured_at)
VALUES ($1::uuid, $2::text, $3::text, $4::text, $5::text, $6::timestamptz)
